#!/usr/bin/env python3

import os
import re

# Mock mountain name database
MOUNTAIN_NAMES = {
    'picture1.jpg': 'Mount Fuji',
    'picture2.jpg': 'Mount Everest',
    'picture3.jpg': 'Rocky Mountains'
}

def rename_mountain_pictures(directory):
    """Rename mountain pictures with their standard common names"""
    print("Renaming mountain pictures...")

    # Get all files in directory
    files = os.listdir(directory)

    for filename in files:
        if filename.lower().endswith(('.jpg', '.jpeg', '.png', '.gif')):
            # Check if we have a known mountain name for this file
            if filename in MOUNTAIN_NAMES:
                new_name = MOUNTAIN_NAMES[filename] + os.path.splitext(filename)[1]
                old_path = os.path.join(directory, filename)
                new_path = os.path.join(directory, new_name)

                # Rename the file
                os.rename(old_path, new_path)
                print(f"Renamed: {filename} -> {new_name}")
            else:
                print(f"No known mountain name for: {filename}")

if __name__ == "__main__":
    rename_mountain_pictures("/tmp/mountain_rename_test")
EOF
